select dt, count(*) raw_rows, sum(case when passed='0' then 1 else 0 end) passed_zero_rows, sum(case when lpid is null then 1 else 0 end) null_lpid_rows, sum(case when coalesce(lower(trim(cast(luid as varchar))),'') in ('0','','null','other','-','-1') then 1 else 0 end) excluded_uid_rows, sum(case when nullif(trim(askscontent),'') is null and nullif(trim(scontent),'') is null then 1 else 0 end) blank_content_rows from gamelive.gamelive_huya_danmu_log where dt in ('2025-01-01','2025-07-01','2026-01-01','2026-07-01','2026-10-31') group by dt order by dt